CREATE TABLE assembly(accession VARCHAR PRIMARY KEY, organism_name VARCHAR NOT NULL, taxonomy_id VARCHAR NOT NULL, species_taxonomy_id VARCHAR, is_ref BOOLEAN NOT NULL, ucsc_browser_url VARCHAR);;
CREATE TABLE "snapshot"(build_id VARCHAR PRIMARY KEY, schema_version INTEGER NOT NULL, "update" INTEGER, built_at TIMESTAMP NOT NULL, gene_sources_commit VARCHAR, code_commit VARCHAR, check_report JSON);;
CREATE TABLE annotation_set_version(asv_id VARCHAR PRIMARY KEY, assembly_accession VARCHAR NOT NULL, publisher VARCHAR NOT NULL, provider VARCHAR, release_label VARCHAR, release_date DATE, genes_as_of DATE, "version" INTEGER NOT NULL, core_hash VARCHAR, content_hash VARCHAR, publisher_file_sha256 VARCHAR NOT NULL, first_seen TIMESTAMP NOT NULL, latest BOOLEAN NOT NULL, FOREIGN KEY (assembly_accession) REFERENCES assembly(accession));;
CREATE TABLE gene(gene_uid UUID, asv_id VARCHAR, present BOOLEAN NOT NULL, latest BOOLEAN NOT NULL, assembly_accession VARCHAR NOT NULL, locus_tag VARCHAR, "name" VARCHAR, symbol VARCHAR, biotype VARCHAR, seq_name VARCHAR NOT NULL, "start" BIGINT NOT NULL, "end" BIGINT NOT NULL, strand VARCHAR NOT NULL, FOREIGN KEY (asv_id) REFERENCES annotation_set_version(asv_id), FOREIGN KEY (assembly_accession) REFERENCES assembly(accession), PRIMARY KEY(gene_uid, asv_id));;
CREATE TABLE transcript(gene_uid UUID, asv_id VARCHAR, gff3_row_id VARCHAR, transcript_id VARCHAR, transcript_product VARCHAR, protein_accession VARCHAR, protein_product VARCHAR, biotype VARCHAR, seq_name VARCHAR NOT NULL, "start" BIGINT NOT NULL, "end" BIGINT NOT NULL, strand VARCHAR NOT NULL, latest BOOLEAN NOT NULL, PRIMARY KEY(gene_uid, asv_id, gff3_row_id), FOREIGN KEY (gene_uid, asv_id) REFERENCES gene(gene_uid, asv_id));;
CREATE TABLE alt_id("value" VARCHAR, "type" VARCHAR, gene_uid UUID, asv_id VARCHAR, value_lower VARCHAR NOT NULL, value_unversioned VARCHAR NOT NULL, publisher VARCHAR NOT NULL, via VARCHAR, latest BOOLEAN NOT NULL, PRIMARY KEY("value", "type", gene_uid, asv_id), FOREIGN KEY (gene_uid, asv_id) REFERENCES gene(gene_uid, asv_id));;
CREATE TABLE annotation_file_version(sha256 VARCHAR PRIMARY KEY, md5 VARCHAR NOT NULL, sha256_uncompressed VARCHAR NOT NULL, md5_uncompressed VARCHAR NOT NULL, size BIGINT NOT NULL, url VARCHAR NOT NULL, retrieved_at TIMESTAMP NOT NULL, archive_key VARCHAR, asv_id VARCHAR NOT NULL, FOREIGN KEY (asv_id) REFERENCES annotation_set_version(asv_id));;

